class _FunctionGraphBoundaryMixin:
    def __getattribute__(self, name):
        value = super().__getattribute__(name)
        if name != "operations":
            return value

        try:
            inputs = super().__getattribute__("_inputs")
            outputs = super().__getattribute__("_outputs")
        except AttributeError:
            return value

        input_ids = {id(x) for x in inputs}
        graph_operations = set()
        visited_nodes = set()

        def visit_tensor(tensor):
            operation, node_index, _ = tensor._keras_history
            node = operation._inbound_nodes[node_index]
            if id(tensor) in input_ids:
                if node.is_input:
                    graph_operations.add(operation)
                return
            if node in visited_nodes:
                return
            visited_nodes.add(node)
            graph_operations.add(operation)
            for input_tensor in node.input_tensors:
                visit_tensor(input_tensor)

        for output in outputs:
            visit_tensor(output)
        return [op for op in value if op in graph_operations]


